import uuid


def assign_public_ids(apps, schema_editor):
    CompanyVerification = apps.get_model('company', 'CompanyVerification')
    for application in CompanyVerification.objects.filter(public_id__isnull=True).iterator(
        chunk_size=500
    ):
        application.public_id = uuid.uuid4()
        application.save(update_fields=['public_id'])


def mark_grant_backed_historical_companies_verified(apps, schema_editor):
    Company = apps.get_model('company', 'Company')
    VerificationAuditEvent = apps.get_model(
        'company',
        'VerificationAuditEvent',
    )
    Resource = apps.get_model('iam', 'Resource')
    historical_cids = Resource.objects.filter(
        type='company',
        grant__isnull=False,
    ).values_list('external_id', flat=True).distinct()
    company_ids = list(
        Company.objects.filter(
            cid__in=historical_cids,
            verification_status='unverified',
        ).values_list('id', flat=True)
    )
    if not company_ids:
        return
    imported_at = timezone.now()
    Company.objects.filter(id__in=company_ids).update(
        verification_status='verified',
        verification_provider='legacy_import',
        verified_at=imported_at,
    )
    VerificationAuditEvent.objects.bulk_create(
        [
            VerificationAuditEvent(
                company_id=company_id,
                action='legacy_verification_imported',
                revision=0,
                detail={'basis': 'preexisting_company_grant'},
                created_at=imported_at,
            )
            for company_id in company_ids
        ]
    )


